all_text = "".join(raw_pages)
# Limpeza de possíveis quebras e HTML entities
all_text = all_text.replace('&quot;', '"').replace('&q;', '"').replace('&quo;', '"').replace('&qu;', '"')

# Extrair todos os objetos JSON com regex seguro
pattern = re.compile(r'\{\s*"ano"\s*:\s*"(\d{4})"\s*,\s*"tipo_crime"\s*:\s*"([^"]+)"\s*,\s*"mes"\s*:\s*"([^"]+)"\s*,\s*"quantidade"\s*:\s*(\d+)\s*\}')
matches = pattern.findall(all_text)

records = []
for ano, tipo, mes, qtd in matches:
    records.append({
        "ano": ano,
        "tipo_crime": tipo.strip(),
        "mes": mes.strip(),
        "quantidade": int(qtd)
    })

print(f"Total de registros oficiais SSP-SP extraídos: {len(records)}")

with open("data/crimes_data.json", "w", encoding="utf-8") as f:
    json.dump(records, f, ensure_ascii=False, indent=2)

